    Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextColor(TEXT);b.setTextSize(10);b.setAllCaps(false);b.setBackgroundColor(PANEL2);return b;}
    Button small(String s){return btn(s);}
    LinearLayout row(int c){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.HORIZONTAL);x.setGravity(Gravity.CENTER_VERTICAL);x.setBackgroundColor(c);return x;}
    LinearLayout col(int c){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);x.setBackgroundColor(c);return x;}
    LinearLayout.LayoutParams lp(int w,int h){return new LinearLayout.LayoutParams(w<0?w:dp(w),h<0?h:dp(h));}
    LinearLayout.LayoutParams wlp(float w,int h){return new LinearLayout.LayoutParams(0,h<0?LinearLayout.LayoutParams.MATCH_PARENT:dp(h),w);}
    int dp(int x){return Math.round(x*getResources().getDisplayMetrics().density);}
    void setStatus(String s,int c){status.setText(s);status.setTextColor(c);}
    void show(String s){new AlertDialog.Builder(this).setTitle("Aleks Soft DecoderPRO").setMessage(s).setPositiveButton("OK",null).show();}
    void err(Exception e){setStatus("â ERROR",RED);show(e.getClass().getSimpleName()+": "+String.valueOf(e.getMessage()));}
